from pathlib import Path

from taf.transport.ssh import connect


class PCExecutor:
    def __init__(self, host, user, password, ssh_port, remote_dir, python_path, pyro_ip, pyro_port):
        self._host = host
        self._user = user
        self._password = password
        self._remote_dir = remote_dir
        self._python = python_path
        self._pyro_ip = pyro_ip
        self._pyro_port = pyro_port
        self._ssh_port = ssh_port
        self.server_startup_timeout = 10
        self.server_welcoming_msg = "Entering request loop"
        self.pc_connection = None
        self.process = None

    def __enter__(self):
        if self.pc_connection is None:
            self.pc_connection = connect(
                hostname=self._host, username=self._user, password=self._password, port=self._ssh_port
            )
        else:
            self.pc_connection.connect()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.pc_connection.disconnect()

    def scp_server_files(self):
        with self:
            remote_dir = Path(self._remote_dir)
            self._scp_dir(Path(__file__).parent / "pyro_server", remote_dir)
            self.pc_connection.files.put(
                local_path=str(Path(__file__).parent / "launcher.py"),
                remote_path=str(remote_dir / "launcher.py"),
            )

    def _scp_dir(self, local_path, remote_path):
        makedirs_path = remote_path / local_path.name
        self.pc_connection.execute(
            f"{self._python} -c \"import os; os.makedirs('{makedirs_path}', exist_ok=True)\""
        )
        remote_path /= local_path.name
        for path in local_path.iterdir():
            if path.is_file():
                self.pc_connection.files.put(local_path=str(path), remote_path=str(remote_path / path.name))
            elif path.is_dir():
                self._scp_dir(path, remote_path)

    def run_server(self):
        with self:
            cmd = (
                f"{self._python} {str(Path(self._remote_dir) / 'launcher.py')} {self._pyro_ip} "
                + f"{self._pyro_port}"
            )
            self.process = self.pc_connection.send_command(cmd, timeout=self.server_startup_timeout + 5, get_pty=False)

    def download_log(self, local_path, remote_path):
        with self:
            self.pc_connection.files.get(remote_path=str(remote_path), local_path=str(local_path))

    def join_server(self, timeout=30):
        if self.process is not None:
            self.process.join(timeout)
